                     tmp6605 = tmp6527*dxi(i)
                     tmp6606 = tmp6604 + tmp6605
                     tmp6607 = tmp6606*tmp6529
                     tmp6608 = tmp6585*tmp6527
                     tmp6609 = tmp6608*state%xi(i)
                     tmp6610 = tmp6609*tmp6575
                     tmp6611 = 0.5_wp*tmp6610
                     tmp6612 = tmp6607 + tmp6611
                     tmp6613 = tmp6202*tmp6612
                     tmp6614 = tmp6215*tmp6527
                     tmp6615 = tmp6614*state%xi(i)
                     tmp6616 = tmp6615*tmp6529
                     tmp6617 = tmp6613 + tmp6616
                     tmp6618 = tmp6547*tmp6617
                     tmp6619 = 1.1283791670955126_wp*tmp6618
                     tmp6620 = tmp6547*tmp6612
                     tmp6621 = tmp6527**(2)
                     tmp6622 = tmp6286*tmp6621
                     tmp6623 = tmp6622*tmp6276
                     tmp6624 = tmp6623*tmp6547
                     tmp6625 = tmp6624*tmp6617
                     tmp6626 = tmp6625*tmp6202
                     tmp6627 = (-2.0_wp)*tmp6626
                     tmp6628 = tmp6620 + tmp6627
                     tmp6629 = tmp6628*tmp6202
                     tmp6630 = tmp6616*tmp6547
                     tmp6631 = tmp6629 + tmp6630
                     tmp6632 = (-1.1283791670955126_wp)*tmp6631
                     tmp6633 = tmp6619 + tmp6632
                     tmp6634 = tmp6597*tmp6633
                     tmp6291 = tmp6596 + tmp6634
                  end if
                  tmp6635 = state%cx_s18(i)*tmp6291
                  tmp6200 = tmp6200 + tmp6635
               end if
            end do
            tmp6197(j) = tmp6197(j) + tmp6200
         end do
         !$omp end do
         deallocate (tmp6199)
         !$omp end parallel
      end block
      call gemv(state%s12, real(tmp1022, wp), tmp6637, trans="t")
      call gemv(state%s12, aimag(tmp1022), tmp6638, trans="t")
      tmp6636 = cmplx(tmp6637, tmp6638, wp)
      tmp6639 = tmp6197 + tmp6636
      tmp6640 = tmp6639*state%cx_v
      tmp6641 = state%cx_s19*dv
      tmp6642 = tmp6640 + tmp6641
      tmp6643 = tmp3711*state%cx_s20
      tmp6644 = state%cx_s26*tmp1927
      tmp6645 = tmp6643 + tmp6644
      hvp_a = tmp6642 + tmp6645
      tmp6646 = state%cx_s15*tmp1923
      tmp6647 = state%cx_s15*tmp1021
      tmp6648 = tmp6646 + tmp6647
      tmp6649 = tmp6639*state%a
      tmp6650 = state%cx_s19*da
      tmp6651 = tmp6649 + tmp6650
      hvp_v = tmp6648 + tmp6651
   end subroutine iefpcm_complex_tangent_one

   module subroutine iefpcm_complex_response(state, dv, hvp_v, error)
      !> State of iefpcm
      type(iefpcm_complex_state), intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call iefpcm_complex_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[iefpcm_complex_response] call iefpcm_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call iefpcm_complex_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine iefpcm_complex_response

   !> One direction of iefpcm_complex_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_complex_response_one(state, dv, hvp_v, error)
      !> State of iefpcm
      type(iefpcm_complex_state), target, intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp14(:), tmp15(:)
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp5(:), tmp6(:), tmp7(:), tmp8(:), tmp9(:), &
                                  tmp10(:), tmp11(:), tmp12(:), tmp13(:), tmp16(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[iefpcm_complex_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[iefpcm_complex_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_complex_response_one] allocation failed")
         return
      end if

      state%op3%points => state%r
      state%op3%a => state%a
      state%op3%c1 => state%s7
      state%op3%c3 => state%s12
      tmp1 = state%a*dv
      call gemv(state%s12, real(tmp1, wp), tmp3)
      call gemv(state%s12, aimag(tmp1), tmp4)
      tmp2 = cmplx(tmp3, tmp4, wp)
      tmp5 = (-0.15915494309189535_wp)*tmp2
      tmp6 = dv + tmp5
      tmp7 = 0.0_wp
      call state%solver%solve_complex(state%op3, .false., tmp6, tmp7, error)
      if (allocated(error)) return
      tmp8 = state%cx_s15*tmp7
      tmp9 = 0.0_wp
      call state%solver%solve_complex(state%op3, .true., dv, tmp9, error)
      if (allocated(error)) return
      tmp10 = state%cx_s15*tmp9
      tmp11 = tmp8 + tmp10
      tmp12 = state%cx_s17*tmp9
      call gemv(state%s12, real(tmp12, wp), tmp14, trans="t")
      call gemv(state%s12, aimag(tmp12), tmp15, trans="t")
      tmp13 = cmplx(tmp14, tmp15, wp)
      tmp16 = tmp13*state%a
      hvp_v = tmp11 + tmp16
   end subroutine iefpcm_complex_response_one

end submodule pcmgen_gauss_iefpcm_complex_tangent
